#!/usr/bin/env bash
# Patch 80 voor hrmforce-site: de HRM-oplossingen en de adviespagina's worden in
# elke taal gebouwd en vertaald, in plaats van naar het Engels te wijzen.
#
#   bash toepassen-80.sh
#
# Het script doet drie dingen:
#   1. de patch toepassen
#   2. de nieuwe teksten vertalen naar en, de, fr, es, ro, pl, da en sv
#      (40.625 tekens per taal, 325.000 in totaal)
#   3. alles in een commit vastleggen
#
# Daarvoor moet DEEPL_API_KEY in de omgeving staan. Zonder sleutel stopt het
# script voor het vertalen, want dan zouden de pagina's in het Nederlands live
# gaan.
set -euo pipefail
cd "$(dirname "$0")"
[ -d src/i18n ] || { echo "Draai dit vanuit de hoofdmap van hrmforce-site."; exit 1; }

cat > /tmp/80.b64 <<'B64EOF'
