base64 -d /tmp/80.b64 > /tmp/80.patch
# Al toegepast? Dan alleen nog vertalen en vastleggen. Zo kun je het script
# opnieuw draaien nadat je de DeepL-sleutel hebt gezet.
if [ -f src/data/oplossingen-hub.js ]; then
  echo "De patch stond er al in, alleen het vertalen en vastleggen nog."
else
  git apply --unidiff-zero /tmp/80.patch
fi
rm -f /tmp/80.b64 /tmp/80.patch

echo
if [ -z "${DEEPL_API_KEY:-}" ]; then
  echo "DEEPL_API_KEY staat niet in de omgeving."
  echo "De patch staat wel in de bestanden, maar er is nog niets vertaald en"
  echo "nog niets vastgelegd. Zet de sleutel en draai daarna:"
  echo
  echo "  export DEEPL_API_KEY=..."
  echo "  bash toepassen-80.sh"
  echo
  echo "(De patch is dan al toegepast; draai alleen nog het vertaaldeel hieronder.)"
  exit 1
fi

echo "Vertalen van de nieuwe teksten (8 talen, ongeveer 5 minuten)..."
HSF_ONLY=advies-detail.js,advies-hub.js,advies-plan.js,oplossingen.js,oplossingen-hub.js,detailpagina-ui.js \
  node scripts/hsf-translate-content.mjs en de fr es ro pl da sv

git add -A
git commit -q -m "HRM-oplossingen en adviespagina's in elke taal

De oplossingen en de adviespagina's bestonden alleen in de zes brontalen. Een
taal daarbuiten kreeg de Engelse versie, en in het Duits, Frans, Spaans en
Roemeens stond een uitgeklede pagina met links die naar zichzelf wezen. Ze
worden nu overal uit dezelfde bron gebouwd, op de Nederlandse opmaak.

1. /hrm-oplossingen/ en /advies/ en hun detailpagina's lopen via de
   [lang]-routes. De tien losse paginabestanden per taal zijn weg.
2. De teksten staan in src/data/ en gaan door de vertaallaag, inclusief het
   kruimelpad, de knoppen en de slotoproep die eerder in de .astro-bestanden
   stonden.
3. Competentiemanagement en talentmanagement stonden alleen in Sanity en dus
   alleen in de brontalen. Ze staan nu in advies-detail.js en bestaan daarmee
   in elke taal.
4. 96 pagina's erbij, geen enkel adres verdwenen. Het aantal links dat een
   Deense of Poolse bezoeker in het Nederlands liet belanden gaat van 105
   naar 72.

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>"

echo
echo "Patch 80 toegepast, vertaald en vastgelegd. Nu nog: git push"
git log --oneline -1
